changeSet.sql:
-- Crear Roles si no existen
DO $$
BEGIN
IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'airline_admin') THEN
CREATE ROLE airline_admin;
END IF;
IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'airline_staff') THEN
CREATE ROLE airline_staff;
END IF;
END $$;

-- Permisos para Administrador (Todo)
GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO airline_admin;

-- Permisos para Staff (Solo lectura de catálogos y gestión de vuelos)
GRANT SELECT ON ALL TABLES IN SCHEMA public TO airline_staff;
GRANT INSERT, UPDATE ON TABLE flight, flight_segment TO airline_staff;
